public class StopwatchPanelTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static java.awt.Component find(java.awt.Container root, String name) {
        if (name.equals(root.getName())) {
            return root;
        }
        for (java.awt.Component child : root.getComponents()) {
            if (name.equals(child.getName())) {
                return child;
            }
            if (child instanceof java.awt.Container) {
                java.awt.Component result = find((java.awt.Container) child, name);
                if (result != null) {
                    return result;
                }
            }
        }
        return null;
    }

    static String textOf(java.awt.Component c) {
        if (c instanceof javax.swing.JLabel) {
            return ((javax.swing.JLabel) c).getText();
        }
        return "(missing)";
    }

    public static void main(String[] args) {
        try {
            StopwatchPanel panel = new StopwatchPanel();
            java.awt.Component label = find(panel, "ticks");
            java.awt.Component button = find(panel, "startStop");
            check("initial ticks", "0", textOf(label));
            panel.tick();
            panel.tick();
            panel.tick();
            check("after three direct tick() calls", "3", textOf(label));
            javax.swing.Timer t = panel.getTimer();
            check("timer created in constructor", true, t != null);
            if (t != null && button instanceof javax.swing.JButton) {
                check("timer delay is 50 ms", 50, t.getDelay());
                check("timer starts out stopped", false, t.isRunning());
                java.awt.event.ActionEvent fire = new java.awt.event.ActionEvent(
                        t, java.awt.event.ActionEvent.ACTION_PERFORMED, "tick");
                for (java.awt.event.ActionListener al : t.getActionListeners()) {
                    al.actionPerformed(fire);
                }
                check("timer action performs a tick", "4", textOf(label));
                javax.swing.JButton b = (javax.swing.JButton) button;
                b.doClick();
                check("running after one click", true, t.isRunning());
                b.doClick();
                check("stopped after a second click", false, t.isRunning());
                t.stop();
            } else {
                failures++;
                System.out.println("FAIL  timer missing or startStop button not found by name");
            }
        } catch (Exception e) {
            failures++;
            System.out.println("FAIL  unexpected exception: " + e);
        }
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

