import java.awt.event.ActionEvent;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.Timer;

public class StopwatchPanel extends JPanel {

    private final JButton startStop = new JButton("Start/Stop");
    private final JLabel ticks = new JLabel("0");
    private Timer timer;
    private int count = 0;

    public StopwatchPanel() {
        startStop.setName("startStop");
        ticks.setName("ticks");
        add(startStop);
        add(ticks);
        startStop.addActionListener(this::onStartStop);
        timer = new Timer(50, e -> tick());
    }

    Timer getTimer() {
        return timer;
    }

    void tick() {
        count++;
        ticks.setText(String.valueOf(count));
    }

    private void onStartStop(ActionEvent e) {
        if (timer.isRunning()) {
            timer.stop();
        } else {
            timer.start();
        }
    }
}
